import glob, os
import numpy as np, pandas as pd
bad=[]
for f in sorted(glob.glob('data/raw/*/run_*.csv')):
    b=os.path.basename(os.path.dirname(f))
    d=pd.read_csv(f,sep=';') if b=='2026-03-12' else pd.read_csv(f,comment='#')
    t=d.iloc[:,0].values; v=d.iloc[:,1].values
    issues=[]
    if d.isna().any().any(): issues.append('NaN')
    if len(np.unique(t))!=len(t): issues.append('dup t')
    if np.any(np.diff(t)<=0): issues.append('non-monotonic t')
    if v.min()<0 or v.max()>1.2: issues.append(f'V range {v.min():.3f}-{v.max():.3f}')
    # spikes: |diff| > 10x median abs diff
    dv=np.abs(np.diff(v)); med=np.median(dv)
    if dv.max()>20*med: issues.append(f'spike {dv.max()/med:.0f}x')
    if issues: bad.append((os.path.basename(f),b,issues))
print('files with issues:',bad if bad else 'none')
print('columns 2025:',pd.read_csv('data/raw/2025-10-14/run_001.csv',comment='#').columns.tolist())
print('columns 2026:',pd.read_csv('data/raw/2026-03-12/run_021.csv',sep=';').columns.tolist())

